	var div_1 = $.child(section);
	var node_1 = $.child(div_1);

	Logo(node_1, {});

	var div_2 = $.sibling(node_1, 2);
	var h1 = $.child(div_2);
	var text = $.child(h1, true);

	$.reset(h1);

	var p = $.sibling(h1, 2);
	var node_2 = $.child(p);

	$.html(node_2, () => $t()('guidelines.intro'));
	$.reset(p);

	var p_1 = $.sibling(p, 2);
	var text_1 = $.child(p_1, true);

