			$.html(node_3, () => $t()(`guidelines.taskers.${index + 1}.item_${i + 1}`));
			$.reset(li);
			$.append($$anchor, li);
		});

		$.reset(ul);
		$.reset(div_9);
		$.reset(div_8);

		$.template_effect(
			($0, $1) => {
				classes = $.set_class(div_8, 1, 'collapse-arrow join-item border-base-300 collapse border-b', null, classes, $0);
				$.set_text(text_3, $1);
			},
			[
				() => ({
					'collapse-open': openAccordion.taskers === index
				}),
				() => $t()(`guidelines.taskers.${index + 1}.title`)
			]
		);

		$.append($$anchor, div_8);
	});

	$.reset(div_7);
	$.reset(div_6);
	$.reset(div_5);

	var div_10 = $.sibling(div_5, 2);
	var h3_1 = $.child(div_10);
	var text_4 = $.child(h3_1, true);

	$.reset(h3_1);
	$.reset(div_10);

	var div_11 = $.sibling(div_10, 2);
	var div_12 = $.child(div_11);
	var div_13 = $.child(div_12);

	$.each(div_13, 20, () => [0, 1, 2], $.index, ($$anchor, index) => {
		var div_14 = root_4();
		let classes_1;
		var button_1 = $.child(div_14);

		button_1.__click = [on_click_1, toggleAccordion, index];

		var text_5 = $.child(button_1, true);

		$.reset(button_1);

		var div_15 = $.sibling(button_1, 2);
		var ul_1 = $.child(div_15);

		$.each(ul_1, 20, () => Array(5), $.index, ($$anchor, _, i) => {
			var li_1 = root_5();
			var node_4 = $.child(li_1);

			$.html(node_4, () => $t()(`guidelines.taskees.${index + 1}.item_${i + 1}`));
			$.reset(li_1);
			$.append($$anchor, li_1);
		});

		$.reset(ul_1);
		$.reset(div_15);
		$.reset(div_14);

		$.template_effect(
			($0, $1) => {
				classes_1 = $.set_class(div_14, 1, 'collapse-arrow join-item border-base-300 collapse border-b', null, classes_1, $0);
